PREFIX fcd: <https://example.org/fincrime-data#>
SELECT DISTINCT ?account ?customerType ?industry ?tenure ?pep ?risk WHERE {
  VALUES ?txid { 2131053 2204314 2282865 }
  ?tx a fcd:Transaction ; fcd:txId ?txid .
  { ?tx fcd:fromAccount ?account } UNION { ?tx fcd:toAccount ?account }
  ?account fcd:customerType ?customerType ; fcd:onboardingTenureDays ?tenure ; fcd:pepFlag ?pep ; fcd:riskRating ?risk .
  OPTIONAL { ?account fcd:industry ?industry }
}

